cat > ci.tf <<'EOF'
# GitHub Actions OIDC handover for the platform/ingest repository.
#
# Two roles are created: one for `plan` on pull requests (read-only on the
# managed resources) and one for `apply` on merges to main. Neither role has any
# IAM permissions, so CI cannot change its own access.

locals {
  github_repo = "platform/ingest"
  state_arn   = "arn:aws:s3:::ingest-terraform-state"
  state_key   = "ingest/terraform.tfstate"
}

# An account can hold only one provider for this URL. If it already exists,
# import it (`terraform import aws_iam_openid_connect_provider.github <arn>`)
# instead of creating it.
resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    # Only workflows running on main can apply.
    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:ref:refs/heads/main"]
    }
  }
}

# State access shared by both roles. The lock file is written even for plan.
data "aws_iam_policy_document" "state" {
  statement {
    sid       = "StateList"
    actions   = ["s3:ListBucket"]
    resources = [local.state_arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = [local.state_key, "${local.state_key}.tflock"]
    }
  }

  statement {
    sid       = "StateRead"
    actions   = ["s3:GetObject"]
    resources = ["${local.state_arn}/${local.state_key}"]
  }

  statement {
    sid       = "StateLock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${local.state_arn}/${local.state_key}.tflock"]
  }
}

data "aws_iam_policy_document" "plan" {
  source_policy_documents = [data.aws_iam_policy_document.state.json]

  statement {
    sid = "ReadManagedResources"
    actions = [
      "s3:GetBucket*",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
      "s3:GetEncryptionConfiguration",
      "s3:GetAccelerateConfiguration",
      "s3:GetAnalyticsConfiguration",
      "s3:GetInventoryConfiguration",
      "s3:GetMetricsConfiguration",
      "s3:GetIntelligentTieringConfiguration",
      "s3:GetObjectLockConfiguration",
      "s3:ListBucket",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid       = "ReadQueue"
    actions   = ["sqs:GetQueueAttributes", "sqs:ListQueueTags"]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }

  # These calls do not support resource-level restrictions.
  statement {
    sid       = "ReadNonResourceScoped"
    actions   = ["sqs:ListQueues", "dynamodb:ListTables", "s3:ListAllMyBuckets"]
    resources = ["*"]
  }
}

data "aws_iam_policy_document" "apply" {
  source_policy_documents = [data.aws_iam_policy_document.plan.json]

  statement {
    sid       = "ManageBucket"
    actions   = ["s3:CreateBucket", "s3:DeleteBucket", "s3:PutBucket*", "s3:DeleteBucket*", "s3:PutLifecycleConfiguration", "s3:PutEncryptionConfiguration", "s3:PutAccelerateConfiguration"]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid       = "ManageQueue"
    actions   = ["sqs:CreateQueue", "sqs:DeleteQueue", "sqs:SetQueueAttributes", "sqs:TagQueue", "sqs:UntagQueue"]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ManageTable"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

resource "aws_iam_role" "ci_plan" {
  name                 = "ingest-ci-plan"
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_plan" {
  name   = "terraform-plan"
  role   = aws_iam_role.ci_plan.id
  policy = data.aws_iam_policy_document.plan.json
}

resource "aws_iam_role" "ci_apply" {
  name                 = "ingest-ci-apply"
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role_policy" "ci_apply" {
  name   = "terraform-apply"
  role   = aws_iam_role.ci_apply.id
  policy = data.aws_iam_policy_document.apply.json
}

output "ci_plan_role_arn" {
  description = "Role for the pull request plan job (role-to-assume)."
  value       = aws_iam_role.ci_plan.arn
}

output "ci_apply_role_arn" {
  description = "Role for the main-branch apply job (role-to-assume)."
  value       = aws_iam_role.ci_apply.arn
}
EOF
sed -i 's/^data "aws_iam_policy_document" "plan" {$/&/' ci.tf
which terraform && terraform fmt -check && terraform init -backend=false -input=false >/dev/null && terraform validate

